import time
from collections import defaultdict, deque
from dataclasses import dataclass


class RateLimiter:
    """Sliding log: at most `limit` allowed requests in any `window` seconds."""

    def __init__(self, limit, window, clock=time.monotonic):
        self.limit = limit
        self.window = window
        self.clock = clock
        self._log = defaultdict(deque)  # key -> timestamps of allowed requests

    def allow(self, key):
        now = self.clock()
        log = self._log[key]
        while log and log[0] <= now - self.window:
            log.popleft()  # older than the window
        if len(log) >= self.limit:
            return False
        log.append(now)
        return True


@dataclass
class _Bucket:
    tokens: float
    updated: float


class TokenBucket:
    """Each key's bucket holds up to `capacity` tokens, refilled at
    `refill_rate` tokens/second. Refill is computed lazily on access."""

    def __init__(self, capacity, refill_rate, clock=time.monotonic):
        self.capacity = capacity
        self.refill_rate = refill_rate
        self.clock = clock
        self._buckets = {}

    def _refill(self, key):
        now = self.clock()
        bucket = self._buckets.get(key)
        if bucket is None:
            bucket = self._buckets[key] = _Bucket(self.capacity, now)
        else:
            elapsed = now - bucket.updated
            bucket.tokens = min(self.capacity, bucket.tokens + elapsed * self.refill_rate)
            bucket.updated = now
        return bucket

    def allow(self, key, cost=1):
        bucket = self._refill(key)
        if bucket.tokens >= cost:
            bucket.tokens -= cost
            return True
        return False

