def fit_messages(messages, budget):
    kept, used = [], 0
    for message in reversed(messages):          # newest first
        cost = count_tokens(message["content"])
        if used + cost > budget:
            break
        kept.append(message)
        used += cost
    kept.reverse()
    return kept

